insert into public.translations (locale, key, value) values
  ('en', 'guidance.noActiveModel', $json$"no model is turned on — they all start off"$json$::jsonb),
  ('en', 'whatsNew.item.modelsOffByDefault.title', $json$"Models start turned off"$json$::jsonb),
  ('en', 'whatsNew.item.modelsOffByDefault.detail', $json$"New installs and every model an agent lists later now start turned off: you turn on, in Settings › Agents, only the ones you want JayV to use. Models you had already turned on stay on. With none on, a request says so and points to Settings."$json$::jsonb),
  ('en', 'whatsNew.item.loadingSpinner.title', $json$"A spinner on every loading screen"$json$::jsonb),
  ('en', 'whatsNew.item.loadingSpinner.detail', $json$"Wherever a screen waits for data (\"Reading settings…\", usage, plans, system, repositories), a spinner now shows above the message, centered."$json$::jsonb),
  ('en', 'whatsNew.item.launchWithoutSkip.title', $json$"No Skip button on the update screen"$json$::jsonb),
  ('en', 'whatsNew.item.launchWithoutSkip.detail', $json$"The screen that checks for updates when JayV opens no longer has a Skip button. If there is no network or the check fails, the app opens by itself after 10 seconds."$json$::jsonb),
  ('en', 'docs.updates.usage', $json$"On open, a short screen looks for the new version and, if there is one, updates and restarts; there is no skip button, and without a network the app opens by itself after 10 seconds. Found later, a bar offers What changes and Update now. To turn off updating on open: Settings › App › Version. The full history is in What's new, in the command palette, and on the Release notes page of the site."$json$::jsonb),
  ('en', 'docs.agents.usage', $json$"Open Settings, turn on the agents installed on this computer and turn on the models each one may use: models start turned off, including the ones the agent lists later, and nothing runs until at least one is on. Each CLI keeps its own login; no key or password passes through JayV. The System page shows whether each agent is installed and answering."$json$::jsonb),
  ('pt-BR', 'guidance.noActiveModel', $json$"nenhum modelo está ligado — todos começam desligados"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modelsOffByDefault.title', $json$"Os modelos começam desligados"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modelsOffByDefault.detail', $json$"Instalações novas e cada modelo que um agente listar depois agora começam desligados: você liga, em Configurações › Agentes, só os que quer que o JayV use. Os modelos que você já tinha ligado continuam ligados. Sem nenhum ligado, o pedido avisa e aponta para as Configurações."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.loadingSpinner.title', $json$"Um spinner em toda tela de carregamento"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.loadingSpinner.detail', $json$"Sempre que uma tela espera por dados (\"Lendo configurações…\", uso, planos, sistema, repositórios), um spinner aparece no centro, acima da mensagem."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.launchWithoutSkip.title', $json$"Sem botão Pular na tela de atualização"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.launchWithoutSkip.detail', $json$"A tela que procura atualizações ao abrir o JayV não tem mais o botão Pular. Sem rede ou se a consulta falhar, o app abre sozinho depois de 10 segundos."$json$::jsonb),
  ('pt-BR', 'docs.updates.usage', $json$"Ao abrir, uma tela rápida procura a versão nova e, havendo, atualiza e reinicia; não há botão de pular, e sem rede o app abre sozinho depois de 10 segundos. Achada depois, uma barra oferece O que muda e Atualizar agora. Para desligar a atualização ao abrir: Configurações › App › Versão. O histórico completo está em Novidades do JayV, na paleta de comandos, e na página Notas da versão do site."$json$::jsonb),
  ('pt-BR', 'docs.agents.usage', $json$"Abra a Configuração, ligue os agentes instalados neste computador e ligue os modelos que cada um pode usar: os modelos começam desligados, inclusive os que o agente listar depois, e nada roda até haver pelo menos um ligado. Cada CLI mantém o próprio login; nenhuma chave ou senha passa pelo JayV. A página Sistema mostra se cada agente está instalado e respondendo."$json$::jsonb),
  ('es', 'guidance.noActiveModel', $json$"ningún modelo está activado: todos empiezan desactivados"$json$::jsonb),
  ('es', 'whatsNew.item.modelsOffByDefault.title', $json$"Los modelos empiezan desactivados"$json$::jsonb),
  ('es', 'whatsNew.item.modelsOffByDefault.detail', $json$"Las instalaciones nuevas y cada modelo que un agente liste después ahora empiezan desactivados: activas, en Configuración › Agentes, solo los que quieres que JayV use. Los modelos que ya tenías activados siguen activados. Sin ninguno activado, la solicitud lo indica y apunta a Configuración."$json$::jsonb),
  ('es', 'whatsNew.item.loadingSpinner.title', $json$"Un indicador de carga en cada pantalla de espera"$json$::jsonb),
  ('es', 'whatsNew.item.loadingSpinner.detail', $json$"Siempre que una pantalla espera datos («Leyendo la configuración…», uso, planes, sistema, repositorios), aparece un indicador de carga centrado sobre el mensaje."$json$::jsonb),
  ('es', 'whatsNew.item.launchWithoutSkip.title', $json$"Sin botón Omitir en la pantalla de actualización"$json$::jsonb),
  ('es', 'whatsNew.item.launchWithoutSkip.detail', $json$"La pantalla que busca actualizaciones al abrir JayV ya no tiene el botón Omitir. Sin red o si la comprobación falla, la app se abre sola tras 10 segundos."$json$::jsonb),
  ('es', 'docs.updates.usage', $json$"Al abrir, una pantalla breve busca la versión nueva y, si la hay, actualiza y reinicia; no hay botón para omitir, y sin red la app se abre sola tras 10 segundos. Si se encuentra después, una barra ofrece Qué cambia y Actualizar ahora. Para desactivar la actualización al abrir: Configuración › App › Versión. El historial completo está en Novedades, en la paleta de comandos y en la página Notas de la versión del sitio."$json$::jsonb),
  ('es', 'docs.agents.usage', $json$"Abre Configuración, activa los agentes instalados en este equipo y activa los modelos que cada uno puede usar: los modelos empiezan desactivados, también los que el agente liste después, y nada se ejecuta hasta que haya al menos uno activado. Cada CLI mantiene su propio inicio de sesión; ninguna clave ni contraseña pasa por JayV. La página Sistema muestra si cada agente está instalado y responde."$json$::jsonb),
  ('fr', 'guidance.noActiveModel', $json$"aucun modèle n’est activé — ils démarrent tous désactivés"$json$::jsonb),
  ('fr', 'whatsNew.item.modelsOffByDefault.title', $json$"Les modèles démarrent désactivés"$json$::jsonb),
  ('fr', 'whatsNew.item.modelsOffByDefault.detail', $json$"Les nouvelles installations et chaque modèle qu’un agent liste ensuite démarrent désormais désactivés : vous n’activez, dans Paramètres › Agents, que ceux que JayV doit utiliser. Les modèles déjà activés le restent. Sans aucun modèle activé, la demande l’indique et renvoie aux Paramètres."$json$::jsonb),
  ('fr', 'whatsNew.item.loadingSpinner.title', $json$"Un indicateur de chargement sur chaque écran d’attente"$json$::jsonb),
  ('fr', 'whatsNew.item.loadingSpinner.detail', $json$"Chaque fois qu’un écran attend des données (« Lecture des paramètres… », utilisation, forfaits, système, dépôts), un indicateur de chargement s’affiche désormais, centré, au-dessus du message."$json$::jsonb),
  ('fr', 'whatsNew.item.launchWithoutSkip.title', $json$"Plus de bouton Passer sur l’écran de mise à jour"$json$::jsonb),
  ('fr', 'whatsNew.item.launchWithoutSkip.detail', $json$"L’écran qui recherche les mises à jour à l’ouverture de JayV n’a plus de bouton Passer. Sans réseau ou si la vérification échoue, l’application s’ouvre d’elle-même après 10 secondes."$json$::jsonb),
  ('fr', 'docs.updates.usage', $json$"À l’ouverture, un court écran cherche la nouvelle version et, s’il y en a une, met à jour et redémarre ; il n’y a pas de bouton pour passer, et sans réseau l’application s’ouvre d’elle-même après 10 secondes. Trouvée plus tard, une barre propose Ce qui change et Mettre à jour maintenant. Pour désactiver la mise à jour à l’ouverture : Paramètres › App › Version. L’historique complet se trouve dans Nouveautés, dans la palette de commandes et sur la page Notes de version du site."$json$::jsonb),
  ('fr', 'docs.agents.usage', $json$"Ouvrez Paramètres, activez les agents installés sur cet ordinateur et activez les modèles que chacun peut utiliser : les modèles démarrent désactivés, y compris ceux que l’agent liste ensuite, et rien ne s’exécute tant qu’aucun n’est activé. Chaque CLI garde sa propre connexion ; aucune clé ni mot de passe ne passe par JayV. La page Système indique si chaque agent est installé et répond."$json$::jsonb),
  ('de', 'guidance.noActiveModel', $json$"kein Modell ist eingeschaltet – alle sind anfangs aus"$json$::jsonb),
  ('de', 'whatsNew.item.modelsOffByDefault.title', $json$"Modelle starten ausgeschaltet"$json$::jsonb),
  ('de', 'whatsNew.item.modelsOffByDefault.detail', $json$"Neue Installationen und jedes Modell, das ein Agent später auflistet, starten jetzt ausgeschaltet: Sie schalten unter Einstellungen › Agenten nur die ein, die JayV verwenden soll. Bereits eingeschaltete Modelle bleiben an. Ist keines eingeschaltet, sagt die Anfrage das und verweist auf die Einstellungen."$json$::jsonb),
  ('de', 'whatsNew.item.loadingSpinner.title', $json$"Ein Ladekreis auf jedem Ladebildschirm"$json$::jsonb),
  ('de', 'whatsNew.item.loadingSpinner.detail', $json$"Wo immer ein Bildschirm auf Daten wartet („Einstellungen werden gelesen…“, Nutzung, Tarife, System, Repositories), erscheint jetzt zentriert über der Meldung ein Ladekreis."$json$::jsonb),
  ('de', 'whatsNew.item.launchWithoutSkip.title', $json$"Kein Überspringen-Button mehr auf dem Update-Bildschirm"$json$::jsonb),
  ('de', 'whatsNew.item.launchWithoutSkip.detail', $json$"Der Bildschirm, der beim Start von JayV nach Updates sucht, hat keinen Überspringen-Button mehr. Ohne Netzwerk oder bei einem Fehler öffnet sich die App nach 10 Sekunden von selbst."$json$::jsonb),
  ('de', 'docs.updates.usage', $json$"Beim Start sucht ein kurzer Bildschirm nach der neuen Version und aktualisiert und startet neu, falls es eine gibt; es gibt keinen Überspringen-Button, und ohne Netzwerk öffnet sich die App nach 10 Sekunden von selbst. Wird sie später gefunden, bietet eine Leiste Was ändert sich und Jetzt aktualisieren an. Zum Ausschalten des Updates beim Start: Einstellungen › App › Version. Den vollständigen Verlauf finden Sie unter Neuigkeiten, in der Befehlspalette und auf der Seite Versionshinweise der Website."$json$::jsonb),
  ('de', 'docs.agents.usage', $json$"Öffnen Sie die Einstellungen, schalten Sie die auf diesem Computer installierten Agenten ein und schalten Sie die Modelle ein, die jeder verwenden darf: Modelle starten ausgeschaltet, auch die, die der Agent später auflistet, und nichts läuft, bis mindestens eines eingeschaltet ist. Jede CLI behält ihre eigene Anmeldung; kein Schlüssel und kein Passwort läuft über JayV. Die Seite System zeigt, ob jeder Agent installiert ist und antwortet."$json$::jsonb),
  ('ru', 'guidance.noActiveModel', $json$"ни одна модель не включена — по умолчанию все выключены"$json$::jsonb),
  ('ru', 'whatsNew.item.modelsOffByDefault.title', $json$"Модели по умолчанию выключены"$json$::jsonb),
  ('ru', 'whatsNew.item.modelsOffByDefault.detail', $json$"Новые установки и каждая модель, которую агент перечислит позже, теперь выключены по умолчанию: в Настройки › Агенты вы включаете только те, которые должен использовать JayV. Уже включённые модели остаются включёнными. Если ни одна не включена, запрос сообщит об этом и направит в настройки."$json$::jsonb),
  ('ru', 'whatsNew.item.loadingSpinner.title', $json$"Индикатор загрузки на каждом экране ожидания"$json$::jsonb),
  ('ru', 'whatsNew.item.loadingSpinner.detail', $json$"Везде, где экран ждёт данные («Чтение настроек…», использование, тарифы, система, репозитории), теперь по центру над сообщением показывается индикатор загрузки."$json$::jsonb),
  ('ru', 'whatsNew.item.launchWithoutSkip.title', $json$"На экране обновления больше нет кнопки «Пропустить»"$json$::jsonb),
  ('ru', 'whatsNew.item.launchWithoutSkip.detail', $json$"На экране проверки обновлений при запуске JayV больше нет кнопки «Пропустить». Без сети или при сбое проверки приложение откроется само через 10 секунд."$json$::jsonb),
  ('ru', 'docs.updates.usage', $json$"При запуске короткий экран ищет новую версию и, если она есть, обновляет и перезапускает приложение; кнопки пропуска нет, а без сети приложение откроется само через 10 секунд. Если версия найдена позже, панель предлагает «Что изменилось» и «Обновить сейчас». Отключить обновление при запуске: Настройки › Приложение › Версия. Полная история — в «Что нового», в палитре команд и на странице «Примечания к версии» на сайте."$json$::jsonb),
  ('ru', 'docs.agents.usage', $json$"Откройте Настройки, включите установленные на этом компьютере агенты и включите модели, которые каждый может использовать: модели по умолчанию выключены, в том числе те, что агент перечислит позже, и ничего не запускается, пока не включена хотя бы одна. Каждый CLI хранит свой вход; ни ключ, ни пароль не проходят через JayV. Страница «Система» показывает, установлен ли каждый агент и отвечает ли он."$json$::jsonb),
  ('zh-CN', 'guidance.noActiveModel', $json$"没有启用任何模型——所有模型默认关闭"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modelsOffByDefault.title', $json$"模型默认关闭"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modelsOffByDefault.detail', $json$"全新安装以及代理之后列出的每个模型现在都默认关闭：你只需在 设置 › 代理 中打开希望 JayV 使用的模型。已经打开的模型保持打开。如果一个都没打开，请求会提示并指向设置。"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.loadingSpinner.title', $json$"所有加载界面都有加载动画"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.loadingSpinner.detail', $json$"凡是界面在等待数据时（“正在读取设置…”、用量、套餐、系统、仓库），现在都会在消息上方居中显示加载动画。"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.launchWithoutSkip.title', $json$"更新界面不再有“跳过”按钮"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.launchWithoutSkip.detail', $json$"JayV 启动时检查更新的界面不再有“跳过”按钮。如果没有网络或检查失败，应用会在 10 秒后自动打开。"$json$::jsonb),
  ('zh-CN', 'docs.updates.usage', $json$"打开时，一个简短的界面会检查新版本，如有则更新并重启；没有跳过按钮，没有网络时应用会在 10 秒后自动打开。稍后发现新版本时，会出现一个提示栏，提供“更新内容”和“立即更新”。要关闭打开时更新：设置 › 应用 › 版本。完整历史记录在“新功能”、命令面板以及网站的“发布说明”页面中。"$json$::jsonb),
  ('zh-CN', 'docs.agents.usage', $json$"打开设置，启用这台电脑上已安装的代理，并启用每个代理可使用的模型：模型默认关闭（包括代理之后列出的模型），至少启用一个之后才会运行。每个 CLI 保留自己的登录；任何密钥或密码都不会经过 JayV。“系统”页面会显示每个代理是否已安装并有响应。"$json$::jsonb),
  ('ja', 'guidance.noActiveModel', $json$"有効なモデルがありません — すべて最初はオフです"$json$::jsonb),
  ('ja', 'whatsNew.item.modelsOffByDefault.title', $json$"モデルは最初はオフです"$json$::jsonb),
  ('ja', 'whatsNew.item.modelsOffByDefault.detail', $json$"新規インストールと、エージェントが後から一覧に出すすべてのモデルは、最初はオフになります。設定 › エージェントで、JayV に使わせたいものだけをオンにしてください。すでにオンにしていたモデルはそのままです。ひとつもオンでない場合、リクエストはその旨を伝えて設定を案内します。"$json$::jsonb),
  ('ja', 'whatsNew.item.loadingSpinner.title', $json$"すべての読み込み画面にスピナーを表示"$json$::jsonb),
  ('ja', 'whatsNew.item.loadingSpinner.detail', $json$"画面がデータを待つ場所（「設定を読み込み中…」、使用量、プラン、システム、リポジトリ）では、メッセージの上に中央揃えでスピナーが表示されます。"$json$::jsonb),
  ('ja', 'whatsNew.item.launchWithoutSkip.title', $json$"更新画面にスキップボタンはなくなりました"$json$::jsonb),
  ('ja', 'whatsNew.item.launchWithoutSkip.detail', $json$"JayV 起動時に更新を確認する画面から、スキップボタンがなくなりました。ネットワークがない場合や確認に失敗した場合は、10 秒後に自動で開きます。"$json$::jsonb),
  ('ja', 'docs.updates.usage', $json$"起動時に短い画面が新しいバージョンを確認し、あれば更新して再起動します。スキップボタンはなく、ネットワークがない場合は 10 秒後に自動で開きます。あとから見つかった場合は、バーに「変更内容」と「今すぐ更新」が表示されます。起動時の更新をオフにするには、設定 › アプリ › バージョンへ。すべての履歴は「新機能」、コマンドパレット、サイトのリリースノートのページにあります。"$json$::jsonb),
  ('ja', 'docs.agents.usage', $json$"設定を開き、このコンピューターにインストールされているエージェントをオンにし、それぞれが使えるモデルをオンにします。モデルは最初はオフで（エージェントが後から一覧に出すものも同様）、1 つ以上オンにするまで何も実行されません。各 CLI は自分のログインを保持し、キーやパスワードが JayV を通ることはありません。システムページで、各エージェントがインストール済みで応答しているかを確認できます。"$json$::jsonb),
  ('hi', 'guidance.noActiveModel', $json$"कोई मॉडल चालू नहीं है — सभी शुरुआत में बंद रहते हैं"$json$::jsonb),
  ('hi', 'whatsNew.item.modelsOffByDefault.title', $json$"मॉडल शुरुआत में बंद रहते हैं"$json$::jsonb),
  ('hi', 'whatsNew.item.modelsOffByDefault.detail', $json$"नई स्थापनाओं में और एजेंट द्वारा बाद में सूचीबद्ध हर मॉडल अब शुरुआत में बंद रहता है: सेटिंग › एजेंट में आप केवल वही चालू करते हैं जिन्हें JayV उपयोग करे। पहले से चालू मॉडल चालू ही रहते हैं। कोई भी चालू न हो तो अनुरोध यह बताता है और सेटिंग की ओर इशारा करता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.loadingSpinner.title', $json$"हर लोडिंग स्क्रीन पर स्पिनर"$json$::jsonb),
  ('hi', 'whatsNew.item.loadingSpinner.detail', $json$"जहाँ भी कोई स्क्रीन डेटा की प्रतीक्षा करती है (\"सेटिंग पढ़ी जा रही हैं…\", उपयोग, प्लान, सिस्टम, रिपॉजिटरी), अब संदेश के ऊपर बीच में एक स्पिनर दिखता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.launchWithoutSkip.title', $json$"अपडेट स्क्रीन पर अब छोड़ें बटन नहीं है"$json$::jsonb),
  ('hi', 'whatsNew.item.launchWithoutSkip.detail', $json$"JayV खुलते समय अपडेट जाँचने वाली स्क्रीन में अब छोड़ें बटन नहीं है। नेटवर्क न होने या जाँच विफल होने पर ऐप 10 सेकंड बाद अपने आप खुल जाता है।"$json$::jsonb),
  ('hi', 'docs.updates.usage', $json$"खुलते समय एक छोटी स्क्रीन नया संस्करण खोजती है और मिलने पर अपडेट करके पुनः आरंभ करती है; छोड़ने का कोई बटन नहीं है, और नेटवर्क न होने पर ऐप 10 सेकंड बाद अपने आप खुल जाता है। बाद में मिलने पर एक बार \"क्या बदला\" और \"अभी अपडेट करें\" देता है। खुलते समय अपडेट बंद करने के लिए: सेटिंग › ऐप › संस्करण। पूरा इतिहास नया क्या है में, कमांड पैलेट में और साइट के रिलीज़ नोट्स पेज पर है।"$json$::jsonb),
  ('hi', 'docs.agents.usage', $json$"सेटिंग खोलें, इस कंप्यूटर पर स्थापित एजेंट चालू करें और हर एक जिन मॉडलों का उपयोग कर सकता है उन्हें चालू करें: मॉडल शुरुआत में बंद रहते हैं, एजेंट द्वारा बाद में सूचीबद्ध मॉडल भी, और कम से कम एक चालू होने तक कुछ नहीं चलता। हर CLI अपना लॉगिन खुद रखता है; कोई कुंजी या पासवर्ड JayV से होकर नहीं गुजरता। सिस्टम पेज बताता है कि हर एजेंट स्थापित है और जवाब दे रहा है या नहीं।"$json$::jsonb),
  ('ar', 'guidance.noActiveModel', $json$"لا يوجد نموذج مُفعَّل — جميعها تبدأ مُعطَّلة"$json$::jsonb),
  ('ar', 'whatsNew.item.modelsOffByDefault.title', $json$"النماذج تبدأ مُعطَّلة"$json$::jsonb),
  ('ar', 'whatsNew.item.modelsOffByDefault.detail', $json$"التثبيتات الجديدة وكل نموذج يدرجه الوكيل لاحقًا تبدأ الآن مُعطَّلة: تفعّل في الإعدادات › الوكلاء فقط ما تريد أن يستخدمه JayV. النماذج التي فعّلتها سابقًا تبقى مفعّلة. وإذا لم يكن أيٌّ منها مفعّلًا، يوضح الطلب ذلك ويوجّهك إلى الإعدادات."$json$::jsonb),
  ('ar', 'whatsNew.item.loadingSpinner.title', $json$"مؤشر تحميل في كل شاشة انتظار"$json$::jsonb),
  ('ar', 'whatsNew.item.loadingSpinner.detail', $json$"في كل مكان تنتظر فيه الشاشة بيانات («جارٍ قراءة الإعدادات…»، الاستخدام، الخطط، النظام، المستودعات) يظهر الآن مؤشر تحميل في المنتصف فوق الرسالة."$json$::jsonb),
  ('ar', 'whatsNew.item.launchWithoutSkip.title', $json$"لا يوجد زر تخطي في شاشة التحديث"$json$::jsonb),
  ('ar', 'whatsNew.item.launchWithoutSkip.detail', $json$"شاشة البحث عن التحديثات عند فتح JayV لم يعد فيها زر تخطي. وإذا لم تتوفر شبكة أو فشل الفحص، يفتح التطبيق من تلقاء نفسه بعد 10 ثوانٍ."$json$::jsonb),
  ('ar', 'docs.updates.usage', $json$"عند الفتح تبحث شاشة قصيرة عن الإصدار الجديد وتحدّث وتعيد التشغيل إن وُجد؛ لا يوجد زر تخطي، وبلا شبكة يفتح التطبيق من تلقاء نفسه بعد 10 ثوانٍ. وإذا عُثر عليه لاحقًا يعرض شريط «ما الذي تغيّر» و«التحديث الآن». لإيقاف التحديث عند الفتح: الإعدادات › التطبيق › الإصدار. السجل الكامل في «الجديد» وفي لوحة الأوامر وفي صفحة ملاحظات الإصدار بالموقع."$json$::jsonb),
  ('ar', 'docs.agents.usage', $json$"افتح الإعدادات وفعّل الوكلاء المثبّتين على هذا الحاسوب وفعّل النماذج التي يمكن لكل منهم استخدامها: النماذج تبدأ مُعطَّلة، بما فيها ما يدرجه الوكيل لاحقًا، ولا يعمل شيء حتى يُفعَّل واحد منها على الأقل. يحتفظ كل CLI بتسجيل دخوله؛ ولا يمر أي مفتاح أو كلمة مرور عبر JayV. تعرض صفحة النظام ما إذا كان كل وكيل مثبّتًا ويستجيب."$json$::jsonb)
